intptr_t encode_into_timestamp(ak_enc_ctx *ctx, const Timestamp &o, const Tcs &t) {
  AK_INIT_OR_RETURN();
  // D27: the core's encode entry resets the context (no ak_enc_reset).
  EncObj_Timestamp h;
  h.o = &o;
  h.t = t;
  struct ak_evt_Timestamp vt;
  vt._reserved = NULL;
  struct ak_efix_Timestamp fix = make_timestamp(o, t);
  AK_TAX();
  return ak_encode_Timestamp(&h, ctx, &vt, &fix);
}

