// bytes, every pool `k`, refilled in place after each delivery; `unk_grow` is the
// fallback. Unconsumed buffers stay in the holder's options and are freed here.
struct UnkPool_Timestamp {
  struct ak_dec_Timestamp_opts opts;
  std::vector<struct ak_unk_buf> bufs;
  uint32_t k;
  uint32_t cap;
  uint64_t refills;
};

static void unk_refill_timestamp(void *hv) {
  UnkPool_Timestamp *h = (UnkPool_Timestamp *)hv;
  (void)h;
}

int32_t decode_with_timestamp_pool(ak_dec_ctx *ctx, const uint8_t *b, size_t n, Timestamp *out, uint32_t k, uint32_t cap, uint64_t *refills) {
  UnkPool_Timestamp h;
  unk_opts_timestamp(&h.opts, -1);
  h.k = k;
  h.cap = cap;
  h.refills = 0;
  h.bufs.assign((size_t)0 * k, ak_unk_buf());
  for (size_t i = 0; i < h.bufs.size(); ++i) { h.bufs[i].data = NULL; h.bufs[i].len = 0; h.bufs[i].cap = 0; }
  uint64_t first = 0;
  unk_fill_buf(&h.opts.self.buf, cap, &first);
  unk_refill_timestamp(&h);
  h.refills = 0;
  int32_t rc = decode_with_timestamp_opts(ctx, b, n, out, &h.opts, unk_refill_timestamp, &h);
  // The pre-allocated buffers the decode did not consume are still ours (R-H7).
  for (size_t i = 0; i < h.bufs.size(); ++i) std::free(h.bufs[i].data);
  std::free(h.opts.self.buf.data);
  if (refills) *refills = h.refills;
  return rc;
}

// Decision 11 control: clear every facade bag at position `pos` (plan.unk_positions
// order) -- what decoding with that position's entry zeroed must produce.
void unk_clear_timestamp(Timestamp &o, int pos) {
  switch (pos) {
    case 0: { o.unknown_fields.clear(); } break;
    default: break;
  }
}

static int32_t pull_replay_timestamp(ak_dec_ctx *ctx, void *obj, const uint8_t *r, size_t len, std::vector<int64_t> &toks) {
  size_t at = 0;
  while (at + sizeof(struct ak_bdr_rec) <= len) {
    struct ak_bdr_rec h;
    std::memcpy(&h, r + at, sizeof h);
    const uint8_t *body = r + at + sizeof h;
    at += sizeof h + (size_t)h.bytes;
    if (at > len) break;
    AK_PULL_RECORD();
    switch (((uint64_t)h.op << 32) | h.slot) {
      case ((uint64_t)AK_BDR_APPLY << 32) | 0u:
        apply_timestamp(ctx, obj, reinterpret_cast<const struct ak_dfix_Timestamp *>(body)); break;
      default:
        ak_fail(ctx, AK_ERR_ABI, NULL, 0);
        return AK_ERR_ABI;
    }
  }
  return AK_OK;
}

static thread_local std::vector<int64_t> t_pull_toks_timestamp;
static thread_local std::vector<uint64_t> t_pull_scratch_timestamp;
static int32_t pull_impl_timestamp(ak_dec_ctx *ctx, const uint8_t *b, size_t n, Timestamp *out, bool drain) {
  AK_INIT_OR_RETURN();
  Sink_Timestamp sink;
  sink.out = out;
  sink.base = b;
  sink.refill = NULL;
  sink.hold = NULL;
  int32_t rc = ak_parse_Timestamp(ctx, b, n);
  if (rc < 0) return rc;
  std::vector<int64_t> &toks = t_pull_toks_timestamp;
  toks.clear();
  if (!drain) {
    const uint8_t *p = NULL;
    size_t len = 0;
    rc = ak_bdr_ptr(ctx, &p, &len);
    if (rc < 0) return rc;
    rc = pull_replay_timestamp(ctx, &sink, p, len, toks);
  } else {
    // A host that must COPY: the records drained into its own 8-aligned memory in
    // chunks of at least AK_BDR_MIN_CHUNK (reused), each replayed.
    std::vector<uint64_t> &sc = t_pull_scratch_timestamp;
    if (sc.size() * 8 < AK_BDR_MIN_CHUNK) sc.resize((AK_BDR_MIN_CHUNK + 7) / 8);
    const size_t total = ak_bdr_footprint(ctx);
    ak_bdr_count_forward(ctx, 1);  // footprint takes a const context: counted here (R5)
    size_t cursor = 0;
    while (cursor < total) {
      intptr_t k = ak_bdr_drain(ctx, (uint8_t *)&sc[0], sc.size() * 8, &cursor);
      if (k < 0) return (int32_t)k;
      if (k == 0) break;
      rc = pull_replay_timestamp(ctx, &sink, (const uint8_t *)&sc[0], (size_t)k, toks);
      if (rc < 0) return rc;
    }
  }
  if (rc < 0) return rc;
  AK_HOST_CALL(); return ak_dec_err(ctx);  // what the host functions reported (ak_fail)
}

