      case ((uint64_t)AK_BDR_APPLY << 32) | 0u:
        apply_list_results_response(ctx, obj, reinterpret_cast<const struct ak_dfix_ListResultsResponse *>(body)); break;
      case ((uint64_t)AK_BDR_ADD << 32) | 1u:
