  h.k = k;
  h.cap = cap;
  h.refills = 0;
  h.bufs.assign((size_t)1 * k, ak_unk_buf());
  for (size_t i = 0; i < h.bufs.size(); ++i) { h.bufs[i].data = NULL; h.bufs[i].len = 0; h.bufs[i].cap = 0; }
  h.opts.batches.bufs = k ? &h.bufs[0 * (size_t)k] : NULL;
  h.opts.batches.n = k;
