    // chunks of at least AK_BDR_MIN_CHUNK (reused), each replayed.
    std::vector<uint64_t> &sc = t_pull_scratch_list_metrics_response;
    if (sc.size() * 8 < AK_BDR_MIN_CHUNK) sc.resize((AK_BDR_MIN_CHUNK + 7) / 8);
